package com.xyz.question_bank_management_system.modules.course.service.impl;
import com.xyz.question_bank_management_system.modules.learning.entity.LearningPathProgress;import org.junit.jupiter.api.Test;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class PathEventDetectorImplTest {@Test void detectsWrongAndStagnationThresholds(){LearningPathProgress p=new LearningPathProgress();p.setConsecutiveWrongCount(3);p.setWindowAttemptCount(3);var events=new PathEventDetectorImpl().detect(p,Map.of("recentMasteryGain","0.005"));assertTrue(events.contains("CONSECUTIVE_WRONG"));assertTrue(events.contains("LEARNING_STAGNATION"));}@Test void explicitManualEventIsDetected(){assertTrue(new PathEventDetectorImpl().detect(null,Map.of("type","MANUAL_REPLAN")).contains("MANUAL_REPLAN"));}}
